 key:{approach:"Read → normalise → join → compare → output → explain.",sample:"import pandas as pd\nhr = pd.read_csv('hr_leavers.csv'); users = pd.read_csv('active_users.csv')\nfor df in (hr, users): df['email'] = df['email'].str.strip().str.lower()\nm = hr.merge(users, on='email', how='inner')\nm['leaving_date'] = pd.to_datetime(m['leaving_date']); m['last_sign_in'] = pd.to_datetime(m['last_sign_in'])\nm['still_enabled'] = m['account_enabled'].astype(str).str.lower().eq('true')\nm['signed_in_after'] = m['last_sign_in'] > m['leaving_date']\nissues = m[m['still_enabled'] | m['signed_in_after']]\nissues.to_csv('leaver_exceptions.csv', index=False); print(issues[['name','email','still_enabled','signed_in_after']])\nOutput: S. Iyer (enabled, signed in 20 Sep after leaving 2 Sep), R. Verma (enabled, signed in 3 Oct after leaving 30 Sep). A. Kumar disabled, no later sign-in → OK.",tips:["Normalising data is half the work.","A sign-in after leaving may be an incident — escalate."]},
